package com.mod.htgt6.minecraft1202.Module.Data.Modern;
import java.util.*;import net.minecraft.nbt.*;import net.minecraft.world.*;
public final class NetherFossilData120 extends WorldSavedData{private static final String N="HTGT6NetherFossils120";private final Map<String,Start>s=new HashMap<String,Start>();private final Set<String>d=new HashSet<String>();public NetherFossilData120(){super(N);}public NetherFossilData120(String n){super(n);}public static NetherFossilData120 get(World w){NetherFossilData120 x=(NetherFossilData120)w.loadItemData(NetherFossilData120.class,N);if(x==null){x=new NetherFossilData120();w.setItemData(N,x);}return x;}public Start start(int x,int z){return s.get(x+","+z);}public Start record(int x,int z,int y,long seed,String template,int rotation){Start a=new Start(x,z,y,seed,template,rotation);s.put(x+","+z,a);markDirty();return a;}public Collection<Start> starts(){return new ArrayList<Start>(s.values());}public boolean done(Start a,int x,int z){return d.contains(a.x+","+a.z+">"+x+","+z);}public void doneSet(Start a,int x,int z){if(d.add(a.x+","+a.z+">"+x+","+z))markDirty();}public void readFromNBT(NBTTagCompound n){s.clear();d.clear();NBTTagList l=n.getTagList("Starts",10);for(int i=0;i<l.tagCount();i++){NBTTagCompound q=l.getCompoundTagAt(i);Start a=new Start(q.getInteger("X"),q.getInteger("Z"),q.getInteger("Y"),q.getLong("Seed"),q.getString("Template"),q.getInteger("Rotation"));s.put(a.x+","+a.z,a);}NBTTagList c=n.getTagList("Done",8);for(int i=0;i<c.tagCount();i++)d.add(c.getStringTagAt(i));}public void writeToNBT(NBTTagCompound n){NBTTagList l=new NBTTagList();for(Start a:s.values()){NBTTagCompound q=new NBTTagCompound();q.setInteger("X",a.x);q.setInteger("Z",a.z);q.setInteger("Y",a.y);q.setLong("Seed",a.seed);q.setString("Template",a.template);q.setInteger("Rotation",a.rotation);l.appendTag(q);}n.setTag("Starts",l);NBTTagList c=new NBTTagList();for(String x:d)c.appendTag(new NBTTagString(x));n.setTag("Done",c);}public static final class Start{public final int x,z,y,rotation;public final long seed;public final String template;Start(int x,int z,int y,long seed,String t,int r){this.x=x;this.z=z;this.y=y;this.seed=seed;template=t;rotation=r;}}}
